-- Hidden Gems: the founder's list of 100 (2026-10-18): 30 places (heritage, markets, parks), 35 cafés, 35 restaurants.
--
-- * 11 were already gems (Song Wat, Talat Noi, Soi Nana, Pak Khlong Talat, Sampeng, Phra Sumen Fort, Pipit Banglamphu,
--   Khlong Toei Market, Benjakitti, NANA Coffee Ari, Nai Ek): they keep their texts and get the founder's numbers.
--   "Phra Sumen Fort & Santichaiprakarn Park" is split, as on the list: the fort stays, the park is a new gem.
-- * The first 32 gems that aren't on the list stay published, numbered 101 and up (after the founder's 100).
-- * Places matched to an OpenStreetMap place are linked (place_id, photo). Heritage spots that aren't map places
--   (streets, a church, a shrine) use OpenStreetMap coordinates. Places not in OpenStreetMap, or chains without a
--   clear branch, start unpublished at an approximate pin (check_note says what to set).
-- * Category: 1–30 by type, 31–65 cafés, 66–100 food. Prices and hours are ranges to check, not promises.

-- Numbers for the existing gems: those not on the list move behind the founder's 100, keeping their order.
update public.gems g
set number = g.number + 100
where g.contributor_id is null and g.number between 1 and 32
  and g.name_en not in (
    'Song Wat Road', 'Talat Noi', 'Soi Nana, Chinatown', 'Pak Khlong Talat Flower Market', 'Sampeng Lane Market',
    'Phra Sumen Fort & Santichaiprakarn Park', 'Pipit Banglamphu Museum', 'Khlong Toei Market', 'Benjakitti Forest Park',
    'NANA Coffee Roasters Ari', 'Nai Ek Roll Noodle'
  );

update public.gems g
set number = m.number
from (values
  ('Song Wat Road', 1), ('Talat Noi', 2), ('Soi Nana, Chinatown', 4), ('Pak Khlong Talat Flower Market', 5),
  ('Sampeng Lane Market', 6), ('Phra Sumen Fort & Santichaiprakarn Park', 17), ('Pipit Banglamphu Museum', 19),
  ('Khlong Toei Market', 28), ('Benjakitti Forest Park', 29), ('NANA Coffee Roasters Ari', 31), ('Nai Ek Roll Noodle', 95)
) as m (name_en, number)
where g.name_en = m.name_en and g.contributor_id is null;

update public.gems g
set name_en = 'Phra Sumen Fort',
    name_th = 'ป้อมพระสุเมรุ',
    subtitle_en = 'Historic fort',
    subtitle_th = 'ป้อมประวัติศาสตร์',
    description_en = 'One of two surviving forts of the old city wall, built in the reign of King Rama I at the river end of Phra Athit Road.',
    description_th = 'หนึ่งในสองป้อมที่เหลืออยู่ของกำแพงพระนคร สร้างในสมัยรัชกาลที่ 1 อยู่ปลายถนนพระอาทิตย์ริมแม่น้ำ',
    hours_en = 'The fort can be seen from outside at any time; the park around it opens daytime to evening.',
    hours_th = 'ชมตัวป้อมจากด้านนอกได้ตลอด สวนรอบป้อมเปิดกลางวันถึงค่ำ',
    tip_en = 'Go in the late afternoon and walk on into Santichaiprakarn Park next door.',
    tip_th = 'ไปช่วงบ่ายแก่ แล้วเดินต่อเข้าสวนสันติชัยปราการที่อยู่ติดกัน'
where g.name_en = 'Phra Sumen Fort & Santichaiprakarn Park' and g.contributor_id is null;

